---Create payment token for a given payment source
---
---Creates a Payment Token from the given payment source and adds it to the Vault of the associated customer.
---
---`POST /v3/vault/payment-tokens`
---Errors: BadRequest, Forbidden, NotFound, UnprocessableEntity.
---@param input paypal.vault_payment_tokens_v3.CreatePaymentTokenRequest
---@return paypal.vault_payment_tokens_v3.PaymentTokenResponse? value
---@return distilled.Error? err
function Client:create_payment_token(input) end

---Create a setup token
---
---Creates a Setup Token from the given payment source and adds it to the Vault of the associated customer.
---
---`POST /v3/vault/setup-tokens`
---Errors: BadRequest, Forbidden, UnprocessableEntity.
---@param input paypal.vault_payment_tokens_v3.CreateSetupTokenRequest
---@return paypal.vault_payment_tokens_v3.SetupTokenResponse? value
---@return distilled.Error? err
function Client:create_setup_token(input) end

---Delete payment token
---
---Delete the payment token associated with the payment token id.
---
---`DELETE /v3/vault/payment-tokens/{id}`
---Errors: BadRequest, Forbidden.
---@param input paypal.vault_payment_tokens_v3.DeletePaymentTokenRequest
---@return paypal.vault_payment_tokens_v3.DeletePaymentTokenResponse? value
---@return distilled.Error? err
function Client:delete_payment_token(input) end

---List all payment tokens
---
---Returns all payment tokens for a customer.
---
---`GET /v3/vault/payment-tokens`
---Errors: BadRequest, Forbidden.
---@param input paypal.vault_payment_tokens_v3.GetCustomerPaymentTokenRequest
---@return paypal.vault_payment_tokens_v3.CustomerVaultPaymentTokensResponse? value
---@return distilled.Error? err
function Client:get_customer_payment_token(input) end

---Retrieve a payment token
---
---Returns a readable representation of vaulted payment source associated with the payment token id.
---
---`GET /v3/vault/payment-tokens/{id}`
---Errors: Forbidden, NotFound, UnprocessableEntity.
---@param input paypal.vault_payment_tokens_v3.GetPaymentTokenRequest
---@return paypal.vault_payment_tokens_v3.PaymentTokenResponse? value
---@return distilled.Error? err
function Client:get_payment_token(input) end

---Retrieve a setup token
---
---Returns a readable representation of temporarily vaulted payment source associated with the setup token id.
---
---`GET /v3/vault/setup-tokens/{id}`
---Errors: Forbidden, NotFound, UnprocessableEntity.
---@param input paypal.vault_payment_tokens_v3.GetSetupTokenRequest
---@return paypal.vault_payment_tokens_v3.SetupTokenResponse? value
---@return distilled.Error? err
function Client:get_setup_token(input) end

